"""Database abstraction: SQLite (zero setup, default) or PostgreSQL.

The shop deployment uses PostgreSQL; tests and quick trials use SQLite. Both go
through the same tiny adapter so the repository code in :mod:`app.db` never
branches on dialect.

Set ``DATABASE_URL`` to switch engines::

    postgresql://partsid:secret@localhost:5432/partsid
    sqlite:///./data/inventory.db          # explicit, but also the default

Differences handled here, and nowhere else:
  * ``?`` placeholders  ->  ``%s`` for Postgres
  * ``AUTOINCREMENT``   ->  ``GENERATED BY DEFAULT AS IDENTITY``
  * ``lastrowid``       ->  ``INSERT ... RETURNING id``
  * case-insensitive ``LIKE``  ->  ``ILIKE``
  * per-connection pragmas, WAL, and a connection pool for Postgres
"""

from __future__ import annotations

import queue
import sqlite3
import threading
from collections.abc import Iterator, Sequence
from contextlib import contextmanager
from pathlib import Path
from typing import Any

from .config import DB_PATH, settings

SQLITE = "sqlite"
POSTGRES = "postgres"

SQLITE_SCHEMA = """
CREATE TABLE IF NOT EXISTS parts (
    id                 INTEGER PRIMARY KEY AUTOINCREMENT,
    part_name          TEXT NOT NULL,
    oem_part_number    TEXT DEFAULT '',
    alternate_numbers  TEXT DEFAULT '[]',
    superseded_numbers TEXT DEFAULT '[]',
    fitment            TEXT DEFAULT '[]',
    condition          TEXT DEFAULT 'New',
    bin_location       TEXT DEFAULT '',
    quantity           INTEGER DEFAULT 0,
    unit_price         REAL DEFAULT 0,
    currency           TEXT DEFAULT 'KES',
    category           TEXT DEFAULT '',
    technical_notes    TEXT DEFAULT '[]',
    image_path         TEXT DEFAULT '',
    verified           INTEGER DEFAULT 0,
    created_at         TEXT NOT NULL,
    updated_at         TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS movements (
    id         INTEGER PRIMARY KEY AUTOINCREMENT,
    part_id    INTEGER NOT NULL REFERENCES parts(id) ON DELETE CASCADE,
    delta      INTEGER NOT NULL,
    reason     TEXT DEFAULT 'adjustment',
    note       TEXT DEFAULT '',
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS scans (
    id              INTEGER PRIMARY KEY AUTOINCREMENT,
    image_path      TEXT NOT NULL,
    report_json     TEXT NOT NULL,
    matched_part_id INTEGER,
    created_at      TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_parts_oem  ON parts(oem_part_number);
CREATE INDEX IF NOT EXISTS idx_parts_bin  ON parts(bin_location);
CREATE INDEX IF NOT EXISTS idx_parts_name ON parts(part_name);
CREATE INDEX IF NOT EXISTS idx_moves_part ON movements(part_id);
"""

# Identical shape; timestamps and JSON blobs stay TEXT so the same Python code
# reads and writes either engine without adapters.
POSTGRES_SCHEMA = """
CREATE TABLE IF NOT EXISTS parts (
    id                 INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    part_name          TEXT NOT NULL,
    oem_part_number    TEXT DEFAULT '',
    alternate_numbers  TEXT DEFAULT '[]',
    superseded_numbers TEXT DEFAULT '[]',
    fitment            TEXT DEFAULT '[]',
    condition          TEXT DEFAULT 'New',
    bin_location       TEXT DEFAULT '',
    quantity           INTEGER DEFAULT 0,
    unit_price         DOUBLE PRECISION DEFAULT 0,
    currency           TEXT DEFAULT 'KES',
    category           TEXT DEFAULT '',
    technical_notes    TEXT DEFAULT '[]',
    image_path         TEXT DEFAULT '',
    verified           INTEGER DEFAULT 0,
    created_at         TEXT NOT NULL,
    updated_at         TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS movements (
    id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    part_id    INTEGER NOT NULL REFERENCES parts(id) ON DELETE CASCADE,
    delta      INTEGER NOT NULL,
    reason     TEXT DEFAULT 'adjustment',
    note       TEXT DEFAULT '',
    created_at TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS scans (
    id              INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    image_path      TEXT NOT NULL,
    report_json     TEXT NOT NULL,
    matched_part_id INTEGER,
    created_at      TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_parts_oem  ON parts(oem_part_number);
CREATE INDEX IF NOT EXISTS idx_parts_bin  ON parts(bin_location);
CREATE INDEX IF NOT EXISTS idx_parts_name ON parts(part_name);
CREATE INDEX IF NOT EXISTS idx_moves_part ON movements(part_id);
"""


class StorageError(RuntimeError):
    """Configuration or connection problem worth showing the operator verbatim."""


# ── dialect helpers ───────────────────────────────────────────────────────
def resolve_dsn(database_url: str = "") -> str:
    """Effective DSN: explicit argument, then settings, then the SQLite default."""
    dsn = (database_url or settings.database_url or "").strip()
    if not dsn:
        return f"sqlite:///{DB_PATH}"
    return dsn


def dialect_of(dsn: str) -> str:
    lowered = dsn.lower()
    if lowered.startswith(("postgres://", "postgresql://")):
        return POSTGRES
    if lowered.startswith("sqlite"):
        return SQLITE
    raise StorageError(
        f"Unsupported DATABASE_URL scheme in {mask_dsn(dsn)!r}. "
        "Use postgresql://... or sqlite:///path/to/file.db"
    )


def mask_dsn(dsn: str) -> str:
    """Hide the password so it is safe to print in logs and diagnostics."""
    if "://" not in dsn:
        return dsn
    scheme, _, rest = dsn.partition("://")
    if "@" not in rest:
        return dsn
    creds, _, host = rest.rpartition("@")
    user = creds.split(":", 1)[0]
    return f"{scheme}://{user}:***@{host}"


def sqlite_path_of(dsn: str) -> Path:
    if dsn.startswith("sqlite:///"):
        return Path(dsn[len("sqlite:///") :])
    if dsn.startswith("sqlite://"):
        return Path(dsn[len("sqlite://") :])
    raise StorageError(f"not a sqlite DSN: {mask_dsn(dsn)}")


# ── cursor / connection wrappers ──────────────────────────────────────────
class Cursor:
    """Uniform result object over sqlite3 and psycopg cursors."""

    __slots__ = ("_cursor", "lastrowid")

    def __init__(self, cursor: Any, lastrowid: int | None = None) -> None:
        self._cursor = cursor
        self.lastrowid = lastrowid

    def fetchone(self) -> Any:
        return self._cursor.fetchone()

    def fetchall(self) -> list[Any]:
        return self._cursor.fetchall()

    @property
    def rowcount(self) -> int:
        return int(getattr(self._cursor, "rowcount", -1) or 0)


class Connection:
    """Thin wrapper: `?` placeholders in, dialect-correct statements out."""

    def __init__(self, raw: Any, dialect: str) -> None:
        self.raw = raw
        self.dialect = dialect

    # -- SQL translation ---------------------------------------------------
    def _translate(self, sql: str) -> str:
        return sql.replace("?", "%s") if self.dialect == POSTGRES else sql

    def execute(self, sql: str, params: Sequence[Any] = ()) -> Cursor:
        cur = self.raw.cursor()
        cur.execute(self._translate(sql), tuple(params))
        return Cursor(cur)

    def insert(self, sql: str, params: Sequence[Any] = ()) -> Cursor:
        """INSERT that guarantees the new row id on both engines."""
        statement = self._translate(sql)
        cur = self.raw.cursor()
        if self.dialect == POSTGRES:
            if "returning" not in statement.lower():
                statement = statement.rstrip().rstrip(";") + " RETURNING id"
            cur.execute(statement, tuple(params))
            row = cur.fetchone()
            new_id = int(row["id"]) if isinstance(row, dict) else int(row[0])
            return Cursor(cur, lastrowid=new_id)
        cur.execute(statement, tuple(params))
        return Cursor(cur, lastrowid=int(cur.lastrowid or 0))

    def executescript(self, script: str) -> None:
        if self.dialect == POSTGRES:
            cur = self.raw.cursor()
            for statement in script.split(";"):
                if statement.strip():
                    cur.execute(statement)
            return
        self.raw.executescript(script)

    @property
    def like(self) -> str:
        """Case-insensitive LIKE keyword for this engine."""
        return "ILIKE" if self.dialect == POSTGRES else "LIKE"

    @property
    def name_order(self) -> str:
        """Case-insensitive ordering expression."""
        return "LOWER(part_name)" if self.dialect == POSTGRES else "part_name COLLATE NOCASE"


# ── Postgres pool ─────────────────────────────────────────────────────────
_pool_lock = threading.Lock()
_pool: queue.LifoQueue | None = None
_pool_dsn = ""
_POOL_SIZE = 4


def _require_psycopg():
    try:
        import psycopg
        from psycopg.rows import dict_row
    except ModuleNotFoundError as exc:  # pragma: no cover - depends on install
        raise StorageError(
            "PostgreSQL support needs psycopg. Install it with:\n"
            '    pip install "psycopg[binary]"\n'
            "or switch back to SQLite by unsetting DATABASE_URL."
        ) from exc
    return psycopg, dict_row


def _pg_pool(dsn: str) -> queue.LifoQueue:
    global _pool, _pool_dsn
    with _pool_lock:
        if _pool is None or _pool_dsn != dsn:
            _pool = queue.LifoQueue(maxsize=_POOL_SIZE)
            _pool_dsn = dsn
        return _pool


def _pg_connect(dsn: str):
    psycopg, dict_row = _require_psycopg()
    try:
        return psycopg.connect(dsn, row_factory=dict_row, connect_timeout=5)
    except psycopg.OperationalError as exc:
        reason = str(exc).splitlines()[0].strip()
        raise StorageError(
            f"Cannot reach PostgreSQL at {mask_dsn(dsn)}: {reason}\n"
            "Check that the server is running, the database exists, and "
            "DATABASE_URL has the right user/password/host."
        ) from exc


def _pg_acquire(dsn: str):
    """Take a live connection from the pool, or open a new one."""
    pool = _pg_pool(dsn)
    try:
        raw = pool.get_nowait()
    except queue.Empty:
        return _pg_connect(dsn)

    try:
        if getattr(raw, "closed", False) or getattr(raw, "broken", False):
            raise ConnectionError("pooled connection is closed")
        with raw.cursor() as probe:
            probe.execute("SELECT 1")
        raw.rollback()  # clear the transaction the probe opened
        return raw
    except Exception:  # noqa: BLE001 - stale/dropped connection: replace it
        try:
            raw.close()
        except Exception:  # noqa: BLE001
            pass
        return _pg_connect(dsn)


@contextmanager
def _postgres_connection(dsn: str) -> Iterator[Connection]:
    raw = _pg_acquire(dsn)
    pool = _pg_pool(dsn)
    try:
        yield Connection(raw, POSTGRES)
        raw.commit()
    except Exception:
        try:
            raw.rollback()
        except Exception:  # noqa: BLE001 - a dead socket cannot roll back
            raw = None
        raise
    finally:
        if raw is not None and not getattr(raw, "closed", True):
            try:
                pool.put_nowait(raw)
            except queue.Full:
                raw.close()


@contextmanager
def _sqlite_connection(path: Path) -> Iterator[Connection]:
    path.parent.mkdir(parents=True, exist_ok=True)
    raw = sqlite3.connect(path, timeout=15)
    raw.row_factory = sqlite3.Row
    raw.execute("PRAGMA foreign_keys = ON")
    raw.execute("PRAGMA busy_timeout = 8000")
    try:
        yield Connection(raw, SQLITE)
        raw.commit()
    except Exception:
        raw.rollback()
        raise
    finally:
        raw.close()


@contextmanager
def connection(dsn: str = "") -> Iterator[Connection]:
    """Open a connection for the configured engine."""
    effective = resolve_dsn(dsn)
    dialect = dialect_of(effective)
    if dialect == POSTGRES:
        with _postgres_connection(effective) as conn:
            yield conn
        return
    with _sqlite_connection(sqlite_path_of(effective)) as conn:
        yield conn


def init_schema(dsn: str = "") -> str:
    """Create tables/indexes if absent. Returns the dialect used."""
    effective = resolve_dsn(dsn)
    dialect = dialect_of(effective)
    with connection(effective) as conn:
        conn.executescript(POSTGRES_SCHEMA if dialect == POSTGRES else SQLITE_SCHEMA)
        if dialect == SQLITE:
            conn.execute("PRAGMA journal_mode = WAL")
    return dialect


def reset_schema(dsn: str = "") -> None:
    """Drop everything - used by tests against a real server."""
    effective = resolve_dsn(dsn)
    if dialect_of(effective) == POSTGRES:
        with connection(effective) as conn:
            conn.execute("DROP TABLE IF EXISTS scans")
            conn.execute("DROP TABLE IF EXISTS movements")
            conn.execute("DROP TABLE IF EXISTS parts")
        return
    path = sqlite_path_of(effective)
    if path.exists():
        path.unlink()


def server_version(dsn: str = "") -> str:
    effective = resolve_dsn(dsn)
    dialect = dialect_of(effective)
    with connection(effective) as conn:
        if dialect == POSTGRES:
            row = conn.execute("SELECT version() AS v").fetchone()
            return str(row["v"]).split(" on ")[0]
        row = conn.execute("SELECT sqlite_version() AS v").fetchone()
        return f"SQLite {row['v']}"


def describe(dsn: str = "") -> dict[str, Any]:
    """Non-secret database diagnostics for /api/health and `check-db`."""
    try:
        effective = resolve_dsn(dsn)
        dialect = dialect_of(effective)
    except StorageError as exc:
        return {
            "dialect": "unknown",
            "dsn": mask_dsn(str(dsn or settings.database_url or "")),
            "source": "DATABASE_URL",
            "connected": False,
            "error": str(exc).splitlines()[0],
        }

    info: dict[str, Any] = {
        "dialect": dialect,
        "dsn": mask_dsn(effective),
        "source": "DATABASE_URL" if (settings.database_url and not dsn) else "default",
    }
    try:
        info["version"] = server_version(effective)
        info["connected"] = True
    except Exception as exc:  # noqa: BLE001 - diagnostics must not raise
        info["connected"] = False
        info["error"] = str(exc).splitlines()[0]
    return info


